# quadtree: subdivide until cells are small or few objects remain
class QT:
    def __init__(self, bounds, cap=2):
        self.bounds, self.cap = bounds, cap
        self.objs, self.kids = [], None
    def insert(self, p):
        x, y, w, h = self.bounds
        if not self.kids:
            self.objs.append(p)
            if len(self.objs) > self.cap and w > 1:
                self.kids = [QT((x, y, w/2, h/2), self.cap), QT((x+w/2, y, w/2, h/2), self.cap),
                             QT((x, y+h/2, w/2, h/2), self.cap), QT((x+w/2, y+h/2, w/2, h/2), self.cap)]
                for o in self.objs:
                    self._put(o)
                self.objs = []
            return
        self._put(p)
    def _put(self, p):
        x, y, w, h = self.bounds
        i = (0 if p[0] < x + w/2 else 1) + (0 if p[1] < y + h/2 else 2)
        self.kids[i].insert(p)
    def query(self, rect):
        x, y, w, h = self.bounds
        qx, qy, qw, qh = rect
        if qx > x + w or qx + qw < x or qy > y + h or qy + qh < y:
            return []
        out = [p for p in self.objs if qx <= p[0] <= qx+qw and qy <= p[1] <= qy+qh]
        if self.kids:
            for k in self.kids:
                out += k.query(rect)
        return out

qt = QT((0, 0, 100, 100))
for p in [(10, 10), (80, 80), (12, 11), (50, 50)]:
    qt.insert(p)
print('in rect (0,0,20,20):', qt.query((0, 0, 20, 20)))

# LOD: representation depends on zoom; far zoom aggregates
def render(node_count, zoom):
    if zoom < 0.5:
        clusters = max(1, node_count // 1000)
        return 'draw %d cluster dots (aggregated)' % clusters
    if zoom < 2:
        return 'draw %d boxes (medium)' % node_count
    return 'draw %d full-detail nodes' % node_count

for z in (0.1, 1.0, 5.0):
    print('zoom %4.1f: %s' % (z, render(50000, z)))
print('frame rate constant as you zoom out: detail follows pixels, not data')

# presence: viewports + cursors broadcast, rendered as overlays
presence = {
    'ada': {'cursor': (120, 80), 'color': 'red', 'viewport': (0, 0, 800, 600)},
    'grace': {'cursor': (400, 300), 'color': 'blue', 'viewport': (200, 100, 800, 600)},
}
me = 'ada'
for user, p in presence.items():
    if user == me:
        continue  # never render your own cursor back at you
    print('render %s caret at %s with name flag (follow mode available)' % (p['color'], p['cursor']))
print('document state: CRDT; cursors: ephemeral presence (10Hz, interpolated)')
